package net.civeira.phylax.feature.observe.observedsource.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSource;
import net.civeira.phylax.feature.observe.observedsource.domain.valueobject.NameVO;

@RequiredArgsConstructor
public class NameValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<NameVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<String> getName() {
    return value.flatMap(NameVO::getName);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<NameVO> getNameValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param name
   * @return
   */
  public T name(NameVO name) {
    this.value = Optional.of(name);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param name
   * @return
   */
  public T name(Optional<NameVO> name) {
    this.value = name;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param name
   * @return
   */
  public T name(String name) {
    this.value = Optional.of(NameVO.from(name));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T nameNull() {
    this.value = Optional.of(NameVO.nullValue());
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public NameVO readName(final Optional<ObservedSource> original, final ConstraintFailList fails) {
    return value.orElse(original.map(ObservedSource::getNameValue).orElseGet(NameVO::nullValue));
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetName() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetNameIfMatches(final String field) {
    if ("name".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
